//! Circuit seams and field codec for noir-zk.
//!
//! Ported from psonet's `pso-protocol` (its `protocol::zk` seams and `codec`)
//! without its `Suite` abstraction: every circuit here is compiled for BN254,
//! so the field is fixed to [`Field`] (`ark_bn254::Fr`). Circuit types and
//! registries are generated by `noir-zk-codegen`; proving and verification
//! live in `noir-zk-backend`.

pub mod artifacts;
pub mod codec;
pub mod error;
pub mod fold;
pub mod registry;
pub mod zk;

pub use artifacts::{Artifacts, VkPath};
pub use codec::{from_fields, FieldElement, FieldEncode, FieldReader, FromFields};
pub use error::Error;
pub use fold::{
    App, AppDispatch, AppStep, AppVisitor, Kernel, KernelInputs, StepInputs, VkInput, Wrapped,
};
pub use registry::{RegistryEntry, Status};
pub use zk::{Circuit, CircuitId, CircuitKind, Field, ProofGenerator, ProofVerifier};
